namespace AccessControl;

public sealed class AccessDecisionEngine
{
    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        var validationFailure = ValidateContext(principal, resource, request);
        if (validationFailure is not null)
            return validationFailure;

        var validPrincipal = principal!;
        var validResource = resource!;
        var validRequest = request!;
        var permissions = GetPermissions(validPrincipal, validResource, validRequest, delegations);

        var policyDecision = EvaluatePolicies(validResource, validRequest, permissions);
        return policyDecision ?? CreateSuccessfulDecision(validResource, validRequest, permissions.Delegated);
    }

    private static AccessDecision? ValidateContext(Principal? principal, Resource? resource, AccessRequest? request)
    {
        if (principal is null || resource is null || request is null)
            return Deny("missing-context");
        if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
            return Deny("invalid-identity");
        if (principal.Suspended)
            return Deny("principal-suspended");
        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
            return Deny("tenant-mismatch");
        if (resource.Locked && request.Action != "read")
            return Deny("resource-locked");
        if (request.MinuteOfDay is < 0 or > 1439)
            return Deny("invalid-time");
        if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
            return Deny("challenge-required");

        return null;
    }

    private static Permissions GetPermissions(
        Principal principal,
        Resource resource,
        AccessRequest request,
        IDelegationRegister delegations)
    {
        return new Permissions(
            principal.Roles.Contains("administrator"),
            principal.Roles.Contains("operator"),
            principal.Roles.Contains("auditor"),
            principal.Id == resource.OwnerId,
            delegations.HasDelegation(principal.Id, resource.Id, request.Action));
    }

    private static AccessDecision? EvaluatePolicies(
        Resource resource,
        AccessRequest request,
        Permissions permissions)
    {
        if (request.BreakGlass)
            return EvaluateBreakGlass(request, permissions.Administrator);

        var restrictionFailure = EvaluateResourceRestrictions(resource, request);
        if (restrictionFailure is not null)
            return restrictionFailure;

        return EvaluateAction(request.Action, permissions);
    }

    private static AccessDecision EvaluateBreakGlass(AccessRequest request, bool administrator)
    {
        return administrator && request.StrongAuthentication
            ? new AccessDecision(true, "break-glass", true)
            : Deny("invalid-break-glass");
    }

    private static AccessDecision? EvaluateResourceRestrictions(Resource resource, AccessRequest request)
    {
        if (resource.Classification != "restricted")
            return null;
        if (!request.StrongAuthentication)
            return Deny("strong-authentication-required");
        if (request.NetworkZone != "trusted")
            return Deny("trusted-network-required");

        return null;
    }

    private static AccessDecision? EvaluateAction(string action, Permissions permissions)
    {
        return action switch
        {
            "delete" when !permissions.Administrator => Deny("administrator-required"),
            "write" when !permissions.CanWrite => Deny("write-not-authorised"),
            "read" when !permissions.CanRead => new AccessDecision(false, "read-not-authorised", false),
            "read" or "write" or "delete" => null,
            _ => Deny("unknown-action")
        };
    }

    private static AccessDecision CreateSuccessfulDecision(Resource resource, AccessRequest request, bool delegated)
    {
        var outsideBusinessHours = request.MinuteOfDay < 480 || request.MinuteOfDay > 1080;
        var requiresAudit = outsideBusinessHours || resource.Classification == "restricted";
        return new AccessDecision(true, delegated ? "delegated" : "role-or-ownership", requiresAudit);
    }

    private static AccessDecision Deny(string reason) => new(false, reason, true);

    private sealed class Permissions
    {
        public Permissions(bool administrator, bool operatorRole, bool auditor, bool owner, bool delegated)
        {
            Administrator = administrator;
            OperatorRole = operatorRole;
            Auditor = auditor;
            Owner = owner;
            Delegated = delegated;
        }

        public bool Administrator { get; }
        public bool OperatorRole { get; }
        public bool Auditor { get; }
        public bool Owner { get; }
        public bool Delegated { get; }
        public bool CanWrite => Administrator || OperatorRole || Owner || Delegated;
        public bool CanRead => CanWrite || Auditor;
    }
}
